def solve_p_max(m, d, r, sticky_count, keep_numer, target):
    # Returns Fraction p_max
    faces = list(range(1, d+1))
    sticky_set = set(range(sticky_count))  # indices 0..sticky_count-1 are sticky
    p_keep = Fraction(keep_numer, d)
    p_unif = Fraction(1, d)

    total = Fraction(0, 1)
    for x in product(faces, repeat=m):
        best = Fraction(0, 1)
        # choose exactly r dice to reroll
        for R in combinations(range(m), r):
            sum_kept = 0
            for i in range(m):
                if i not in R:
                    sum_kept += x[i]
            residual = target - sum_kept
            if residual < r or residual > r * d:
                # impossible sum for r dice
                continue
            # DP over selected dice distributions
            dp = {0: Fraction(1, 1)}
            for i in R:
                # distribution for die i if rerolled
                if i in sticky_set:
                    v0 = x[i]
                    # For y == v0: p_keep + (1-p_keep)*p_unif; else: (1-p_keep)*p_unif
                    dist = {}
                    one_minus = Fraction(1, 1) - p_keep
                    for y in faces:
                        if y == v0:
                            prob = p_keep + one_minus * p_unif
                        else:
                            prob = one_minus * p_unif
                        dist[y] = prob
                else:
                    # uniform
                    dist = {y: p_unif for y in faces}
                new_dp = {}
                for s0, w0 in dp.items():
                    for y, py in dist.items():
                        s1 = s0 + y
                        new_dp[s1] = new_dp.get(s1, Fraction(0, 1)) + w0 * py
                dp = new_dp
            prob_res = dp.get(residual, Fraction(0, 1))
            if prob_res > best:
                best = prob_res
        total += best
    p_max = total / Fraction(d**m, 1)
    return p_max

def baseline_prob(m, d, target):
    # Probability that sum of m fair d-faced dice equals target
    from fractions import Fraction
    faces = list(range(1, d+1))
    dp = {0: Fraction(1, 1)}
    p_unif = Fraction(1, d)
    for _ in range(m):
        new_dp = {}
        for s0, w0 in dp.items():
            for y in faces:
                s1 = s0 + y
                new_dp[s1] = new_dp.get(s1, Fraction(0, 1)) + w0 * p_unif
        dp = new_dp
    return dp.get(target, Fraction(0, 1))

tries = 0
while True:
    tries += 1
    if tries > 200:
        # fallback to a known-hard instance
        m = 5
        d = 6
        r = 3
        sticky_count = 2
        keep_numer = 4
        target = 16
    else:
        d = 6
        m = rng.choice([4, 5])
