        if r >= m:
            r = m - 1
        sticky_count = rng.choice([1, 2])
        if sticky_count > m:
            sticky_count = m
        keep_numer = rng.randint(1, d-2)  # avoid 0 and d-1 extremes sometimes
        # target near mean m*(d+1)/2
        mean = m * (d + 1) / 2.0
        offset_choices = [-1, 0, 1]
        target = int(round(mean + rng.choice(offset_choices)))
        target = max(m, min(m * d, target))
    # solve and check non-triviality
    p_max = solve_p_max(m, d, r, sticky_count, keep_numer, target)
    base = baseline_prob(m, d, target)
    # Enforce that rerolling actually improves probability and not trivial
    if p_max > base and p_max > Fraction(0, 1):
        scale_factor = d ** (m + r + sticky_count)
        return {
            'm': m,
            'd': d,
            'r': r,
